package rw.qiben;

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@RestController
public class ApiController {
 private final JdbcTemplate db; private final PasswordEncoder encoder; private final JavaMailSender mail; private final String secret,inbox,from; private final boolean secure; private final Map<String,ArrayDeque<Instant>> limits=new ConcurrentHashMap<>();
 ApiController(JdbcTemplate db,PasswordEncoder encoder,JavaMailSender mail,@Value("${qiben.jwt-secret:}") String secret,@Value("${qiben.inbox}") String inbox,@Value("${MAIL_FROM:no-reply@example.com}") String from,@Value("${qiben.cookie-secure:false}") boolean secure){this.db=db;this.encoder=encoder;this.mail=mail;this.secret=secret;this.inbox=inbox;this.from=from;this.secure=secure;}
 public record Contact(@NotBlank @Size(min=2,max=120) String name,@NotBlank @Email @Size(max=254) String email,@NotBlank @Size(max=180) String subject,@NotBlank @Size(min=10,max=5000) String message,String website){}
 public record Signup(@NotBlank @Email @Size(max=254) String email){}
 public record Login(@NotBlank @Email String email,@NotBlank @Size(min=12,max=200) String password){}
 @GetMapping("/api/public/products") List<Map<String,Object>> products(@RequestParam(required=false) Boolean featured){String q="SELECT id,type,name,slug,tagline,short_description AS shortDescription,accent_color AS accentColor,public_url AS publicUrl FROM products WHERE published=TRUE"+(Boolean.TRUE.equals(featured)?" AND featured=TRUE":"")+" ORDER BY display_order,id";return db.queryForList(q);}
 @GetMapping("/api/public/products/{slug}") Map<String,Object> product(@PathVariable String slug){var rows=db.queryForList("SELECT * FROM products WHERE slug=? AND published=TRUE",slug);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.get(0);}
 @GetMapping("/api/public/statistics") List<Map<String,Object>> statistics(){return db.queryForList("SELECT id,label,value,suffix FROM statistics WHERE visible=TRUE ORDER BY display_order,id");}
 private void rate(HttpServletRequest req,String route,int maximum){String ip=Optional.ofNullable(req.getHeader("X-Forwarded-For")).orElse(req.getRemoteAddr()).split(",")[0].trim();String key=route+":"+ip;Instant now=Instant.now();var q=limits.computeIfAbsent(key,k->new ArrayDeque<>());synchronized(q){while(!q.isEmpty()&&q.peekFirst().isBefore(now.minusSeconds(3600)))q.removeFirst();if(q.size()>=maximum)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Please try again later");q.addLast(now);}}
 @PostMapping("/api/public/contact") Map<String,String> contact(@Valid @RequestBody Contact c,HttpServletRequest req){rate(req,"contact",5);if(c.website()!=null&&!c.website().isBlank())return Map.of("status","received");db.update("INSERT INTO contact_messages(name,email,subject,message) VALUES (?,?,?,?)",c.name().trim(),c.email().trim().toLowerCase(),c.subject().trim(),c.message().trim());try{var m=new SimpleMailMessage();m.setFrom(from);m.setTo(inbox);m.setReplyTo(c.email());m.setSubject("Website enquiry: "+c.subject());m.setText("From: "+c.name()+" <"+c.email()+">\n\n"+c.message());mail.send(m);var reply=new SimpleMailMessage();reply.setFrom(from);reply.setTo(c.email());reply.setSubject("We received your message");reply.setText("Thank you for contacting Qiben. Our team will get back to you shortly.");mail.send(reply);}catch(Exception ignored){}return Map.of("status","received");}
 @PostMapping("/api/public/newsletter") Map<String,String> subscribe(@Valid @RequestBody Signup s,HttpServletRequest req){rate(req,"newsletter",8);db.update("INSERT INTO newsletter_subscribers(email) VALUES (?) ON DUPLICATE KEY UPDATE active=TRUE",s.email().trim().toLowerCase());return Map.of("status","subscribed");}
 @PostMapping("/api/auth/login") Map<String,String> login(@Valid @RequestBody Login l,HttpServletRequest req,HttpServletResponse res){rate(req,"login",8);var users=db.queryForList("SELECT id,email,password_hash,failed_logins,locked_until,active FROM admin_users WHERE email=?",l.email().toLowerCase());if(users.isEmpty())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");var u=users.get(0);Integer failed=(Integer)u.get("failed_logins");if(Boolean.FALSE.equals(u.get("active"))||(u.get("locked_until")!=null&&((java.sql.Timestamp)u.get("locked_until")).toInstant().isAfter(Instant.now())))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account temporarily locked");if(!encoder.matches(l.password(),(String)u.get("password_hash"))){int n=failed+1;db.update("UPDATE admin_users SET failed_logins=?,locked_until=? WHERE id=?",n,n>=8?java.sql.Timestamp.from(Instant.now().plusSeconds(900)):null,u.get("id"));throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");}db.update("UPDATE admin_users SET failed_logins=0,locked_until=NULL WHERE id=?",u.get("id"));if(secret.length()<32)throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"JWT_SECRET must be at least 32 characters");String email=(String)u.get("email");String access=token(email,"access",900);String refresh=token(email,"refresh",604800);res.addHeader("Set-Cookie","qiben_refresh="+refresh+"; HttpOnly; SameSite=Strict; Path=/api/auth; Max-Age=604800"+(secure?"; Secure":""));return Map.of("accessToken",access,"tokenType","Bearer");}
 @PostMapping("/api/auth/refresh") Map<String,String> refresh(@CookieValue(value="qiben_refresh",required=false) String cookie){if(cookie==null||secret.length()<32)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{var claims=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(cookie).getPayload();if(!"refresh".equals(claims.get("kind")))throw new IllegalArgumentException();return Map.of("accessToken",token(claims.getSubject(),"access",900));}catch(Exception e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}}
 private String token(String email,String kind,long seconds){return Jwts.builder().subject(email).claim("role","ADMIN").claim("kind",kind).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(seconds))).signWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).compact();}
 @PostMapping("/api/auth/logout") Map<String,String> logout(HttpServletResponse r){r.addHeader("Set-Cookie","qiben_refresh=; HttpOnly; SameSite=Strict; Path=/api/auth; Max-Age=0"+(secure?"; Secure":""));return Map.of("status","logged_out");}
 @GetMapping("/api/admin/dashboard") Map<String,Object> dashboard(){return Map.of("messages",db.queryForObject("SELECT COUNT(*) FROM contact_messages",Integer.class),"newMessages",db.queryForObject("SELECT COUNT(*) FROM contact_messages WHERE status='NEW'",Integer.class),"newThisMonth",db.queryForObject("SELECT COUNT(*) FROM contact_messages WHERE created_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')",Integer.class),"publishedProducts",db.queryForObject("SELECT COUNT(*) FROM products WHERE published=TRUE AND type='PRODUCT'",Integer.class),"publishedProjects",db.queryForObject("SELECT COUNT(*) FROM products WHERE published=TRUE AND type='PROJECT'",Integer.class));}
 @GetMapping("/api/admin/messages") Map<String,Object> messages(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(required=false) String status,@RequestParam(required=false) String search){int p=Math.max(0,page),s=Math.min(100,Math.max(1,size));String filter=" WHERE (? IS NULL OR status=?) AND (? IS NULL OR name LIKE ? OR email LIKE ? OR subject LIKE ?)";var rows=db.queryForList("SELECT * FROM contact_messages"+filter+" ORDER BY created_at DESC LIMIT ? OFFSET ?",status,status,search,search==null?null:"%"+search+"%",search==null?null:"%"+search+"%",search==null?null:"%"+search+"%",s,p*s);Integer total=db.queryForObject("SELECT COUNT(*) FROM contact_messages"+filter,Integer.class,status,status,search,search==null?null:"%"+search+"%",search==null?null:"%"+search+"%",search==null?null:"%"+search+"%");return Map.of("items",rows,"page",p,"size",s,"total",total);}
 @PatchMapping("/api/admin/messages/{id}/status") Map<String,String> setStatus(@PathVariable long id,@RequestBody Map<String,String> body){String status=body.getOrDefault("status","");if(!Set.of("NEW","READ","REPLIED","ARCHIVED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");db.update("UPDATE contact_messages SET status=? WHERE id=?",status,id);return Map.of("status",status);}
 @PostMapping("/api/admin/messages/{id}/notes") Map<String,String> note(@PathVariable long id,@RequestBody Map<String,String> body){String n=body.getOrDefault("note","").trim();if(n.isBlank()||n.length()>5000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Note is required");Long admin=db.queryForObject("SELECT id FROM admin_users ORDER BY id LIMIT 1",Long.class);db.update("INSERT INTO message_notes(message_id,admin_user_id,note) VALUES (?,?,?)",id,admin,n);return Map.of("status","saved");}
 @DeleteMapping("/api/admin/messages/{id}") Map<String,String> deleteMessage(@PathVariable long id){db.update("DELETE FROM contact_messages WHERE id=?",id);return Map.of("status","deleted");}
 @GetMapping("/api/admin/statistics") List<Map<String,Object>> adminStats(){return db.queryForList("SELECT * FROM statistics ORDER BY display_order,id");}
 @PutMapping("/api/admin/statistics/{id}") Map<String,String> updateStat(@PathVariable long id,@RequestBody Map<String,Object>b){db.update("UPDATE statistics SET label=?,value=?,suffix=?,display_order=?,visible=? WHERE id=?",b.get("label"),b.get("value"),b.get("suffix"),b.get("displayOrder"),b.get("visible"),id);return Map.of("status","saved");}
 @GetMapping("/api/admin/products") List<Map<String,Object>> adminProducts(){return db.queryForList("SELECT * FROM products ORDER BY display_order,id");}
 @PostMapping("/api/admin/products") Map<String,Object> createProduct(@RequestBody Map<String,Object>b){db.update("INSERT INTO products(type,name,slug,tagline,short_description,long_description,category,status,featured,accent_color,logo_url,cover_url,public_url,client_name,project_year,display_order,published) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",b.get("type"),b.get("name"),b.get("slug"),b.get("tagline"),b.get("shortDescription"),b.get("longDescription"),b.get("category"),b.getOrDefault("status","IN_DEVELOPMENT"),b.getOrDefault("featured",false),b.getOrDefault("accentColor","#146c66"),b.get("logoUrl"),b.get("coverUrl"),b.get("publicUrl"),b.get("clientName"),b.get("year"),b.getOrDefault("displayOrder",0),b.getOrDefault("published",false));return Map.of("status","created");}
 @PutMapping("/api/admin/products/{id}") Map<String,String> updateProduct(@PathVariable long id,@RequestBody Map<String,Object>b){db.update("UPDATE products SET type=?,name=?,slug=?,tagline=?,short_description=?,long_description=?,category=?,status=?,featured=?,accent_color=?,logo_url=?,cover_url=?,public_url=?,client_name=?,project_year=?,display_order=?,published=? WHERE id=?",b.get("type"),b.get("name"),b.get("slug"),b.get("tagline"),b.get("shortDescription"),b.get("longDescription"),b.get("category"),b.get("status"),b.get("featured"),b.get("accentColor"),b.get("logoUrl"),b.get("coverUrl"),b.get("publicUrl"),b.get("clientName"),b.get("year"),b.get("displayOrder"),b.get("published"),id);return Map.of("status","saved");}
 @DeleteMapping("/api/admin/products/{id}") Map<String,String> deleteProduct(@PathVariable long id){db.update("DELETE FROM products WHERE id=?",id);return Map.of("status","deleted");}
 @GetMapping("/api/admin/messages/{id}/notes") List<Map<String,Object>> notes(@PathVariable long id){return db.queryForList("SELECT n.id,n.note,n.created_at,u.email AS author FROM message_notes n JOIN admin_users u ON u.id=n.admin_user_id WHERE message_id=? ORDER BY n.created_at",id);}
}
